const toggle = document.querySelector("[data-lang-toggle]");
const description = document.querySelector('meta[name="description"]');
let lang = "vi";

function applyLanguage(next, persist = true) {
  lang = next === "en" ? "en" : "vi";
  document.documentElement.lang = lang;

  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const value = translations[lang][element.dataset.i18n];
    if (value) element.textContent = value;
  });

  document.querySelectorAll("[data-i18n-alt]").forEach((element) => {
    const value = translations[lang][element.dataset.i18nAlt];
    if (value) element.alt = value;
  });

  document.querySelectorAll("[data-i18n-aria-label]").forEach((element) => {
    const value = translations[lang][element.dataset.i18nAriaLabel];
    if (value) element.setAttribute("aria-label", value);
  });

  document.title = languageMeta[lang].title;
  description.setAttribute("content", languageMeta[lang].description);
  toggle.textContent = languageMeta[lang].toggleText;
  toggle.setAttribute("aria-label", languageMeta[lang].toggleLabel);

  if (persist) {
    try {
      localStorage.setItem("rawiq-language", lang);
    } catch (_) {
      // The site still works when browser storage is unavailable.
    }
  }
}

toggle.addEventListener("click", () => applyLanguage(lang === "vi" ? "en" : "vi"));
document.getElementById("year").textContent = new Date().getFullYear();

let preferredLanguage = "vi";
try {
  const storedLanguage = localStorage.getItem("rawiq-language");
  if (storedLanguage === "en" || storedLanguage === "vi") preferredLanguage = storedLanguage;
} catch (_) {
  // Vietnamese remains the default when browser storage is unavailable.
}
applyLanguage(preferredLanguage, false);
